insert into public.icon_wishlist (concept,label) select v.concept,v.label from (values ('yogurt-cake','Yogurt cake'),('crumble','Crumble'),('poached-pear','Poached pear with chocolate'),('mont-blanc-pastry','Mont Blanc'),('tropezienne','Tropézienne'),('couscous','Couscous'),('double-bass','Double bass'),('conical-hat','Vietnam'),('dubrovnik-wall','Croatia'),('machu-picchu','Peru'),('bali-temple','Indonesia')) v(concept,label) where not exists (select 1 from public.card_icons c where c.concept=v.concept and c.image is not null) and not exists (select 1 from public.icon_wishlist w where w.concept=v.concept);
